insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('2ead95e7-38f8-5d2e-9e23-0c8e74bc0be4', 'deadlift-specialist', 'Deadlift Specialist', 'Two pulling days — heavy and variation — with hinge accessories, upper-back and grip work.', 'An 8-week block for a stronger deadlift. Deadlifts are very fatiguing, so heavy pulls happen once a week, with a lighter variation day (deficit or block pulls) to target your sticking point. Squats and upper-body work support the pull. Use the custom program builder for loads based on your max.', 'f48c2610-b7ab-5915-b597-4895c2ce9aaa', 'intermediate', 8, 3, 60, array['build_strength', 'type:powerlifting', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'pull_up_bar']::text[], 'plus', 'Target RPE rises by about 0.5 per week. Add 5 kg / 10 lb to the heavy deadlift when all sets are completed at or below the target RPE with a flat back. Week 8 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
