insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('bb9ddb06-3183-530d-8929-77eaa2271c8e', 'physique-show-prep', 'Physique Show Prep', 'Twelve weeks of high-volume hypertrophy, daily steps and planned conditioning, tapering into show week.', 'A training plan for bodybuilding, classic, men''s/women''s physique, figure, bikini and wellness competitors. Five sessions per week keep volume high to hold muscle while conditioning is gradually increased. The final week is a training taper. Nutrition, water and peak-week strategy should be guided by a qualified coach or registered dietitian — this program does not prescribe extreme dieting or dehydration.', 'e2746996-75ef-5993-a5cd-d47a8c68cd71', 'advanced', 12, 5, 75, array['build_muscle', 'lose_fat', 'type:hypertrophy', 'type:cardio']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar', 'bike']::text[], 'plus', 'Add a rep or a small amount of load each week while keeping 1–2 reps in reserve. Add 5 minutes of low-intensity cardio per session every two weeks as needed. Week 12 is a taper: lower volume and keep posing practice daily.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes', '5 minutes posing practice (mandatory poses for your division)']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
