insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('d22e6b2f-346b-593f-8ee4-f50ad6d7cae8', 'speed-development', 'Speed Development', 'Sprint mechanics, acceleration and max velocity with plyometrics and strength — always fully recovered.', 'Three sessions a week to get faster: an acceleration day, a max-velocity day and a strength/power day. Speed is trained fresh with full rest between reps (2–5 minutes) — if a rep feels slower, the session is done. Find a flat track or field.', 'e1f4775a-ff48-5c84-932f-4bede1218c38', 'intermediate', 6, 3, 50, array['athletic_performance', 'type:athletic']::text[], array['bodyweight', 'barbell', 'rack', 'dumbbell', 'box']::text[], 'plus', 'Add one sprint rep or 5 m of distance each week while quality is high. Never trade rest for volume. Week 6 halves volume to let speed show up — time a 20 m or 40 m sprint at the end of it.', array['5 minutes easy jog, skipping or jump rope', 'Leg swings front-to-back and side-to-side × 10 each leg', 'World''s greatest stretch × 3 per side', 'A-skips and wall drills × 2 rounds', '3 build-up runs of 30–40 m at 60%, 75% and 90% effort']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
