insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, is_published, source) values ('4e00bff1-6377-50ce-8e33-1b6102e55ffb', 'agility-footwork', 'Agility & Footwork', 'Ladder footwork, cone drills, reactive work and lateral plyometrics for quicker cuts.', 'Three sessions per week to move faster in any direction. Planned change-of-direction drills teach deceleration and re-acceleration; reactive drills train you to read and respond. Cones can be any markers, and the ladder can be taped or chalked on the floor.', '17a073c8-9e3b-5ec0-a987-fdb4df246597', 'beginner', 6, 3, 45, array['athletic_performance', 'type:athletic']::text[], array['bodyweight', 'dumbbell', 'box', 'band']::text[], 'plus', 'Add one rep per drill each week while every rep stays sharp. Keep rest long enough (60–90 s) that each rep is fast. Week 6 reduces volume — time your 5-10-5 at the end of it.', array['5 minutes easy jog, skipping or jump rope', 'Leg swings front-to-back and side-to-side × 10 each leg', 'World''s greatest stretch × 3 per side', 'A-skips and wall drills × 2 rounds', '3 build-up runs of 30–40 m at 60%, 75% and 90% effort']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, is_published = true;
